function longestMirrorSubseq(s: string): number {
  const go = (i: number, j: number): number => {
    if (i > j) return 0;
    if (i === j) return 1;
    if (s[i] === s[j]) return 2 + go(i + 1, j - 1);
    return Math.max(go(i + 1, j), go(i, j - 1));
  };
  return go(0, s.length - 1);
}

