function longestMirrorSubseq(s: string): number {
  const n = s.length;
  let below = new Array(n).fill(0); // row i + 1
  for (let i = n - 1; i >= 0; i--) {
    const row = new Array(n).fill(0);
    row[i] = 1;
    for (let j = i + 1; j < n; j++) {
      if (s[i] === s[j]) row[j] = 2 + (j - 1 >= i + 1 ? below[j - 1] : 0);
      else row[j] = Math.max(below[j], row[j - 1]);
    }
    below = row;
  }
  return below[n - 1];
}

