class Solution:
    def longestMirrorSubseq(self, s: str) -> int:
        n = len(s)
        below = [0] * n  # row i + 1
        for i in range(n - 1, -1, -1):
            row = [0] * n
            row[i] = 1
            si = s[i]
            for j in range(i + 1, n):
                if si == s[j]:
                    row[j] = 2 + (below[j - 1] if j - 1 >= i + 1 else 0)
                else:
                    row[j] = below[j] if below[j] > row[j - 1] else row[j - 1]
            below = row
        return below[n - 1]

